const menu=document.querySelector('.menu'),navigation=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open)});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const projects={memorybook:{title:'MemoryBook',image:'memorybook',description:'Un espacio para crear álbumes de fotos, personalizar sus páginas y construir recuerdos con otras personas. Un proyecto que une edición visual, colaboración y el encanto de un libro de fotografías.',tags:['React','Editor visual','Colaboración'],repo:'MemoryBook'},filmlab:{title:'FilmLab',image:'filmlab',description:'Un proyecto nacido de mi interés por la fotografía. Una experiencia de edición pensada para experimentar con ajustes, tonos y estilos desde el celular.',tags:['Fotografía','Color','Experiencia móvil']},professional:{title:'FilmLab Professional',image:'filmlab-pro',description:'La exploración de un editor fotográfico de escritorio, con máscaras y ajustes de color. Una interfaz que busca dar más espacio a la imagen y acercar herramientas de edición a un flujo creativo.',tags:['Edición','Máscaras','Interfaz de escritorio']},bimu:{title:'Bimu',image:'bimu',description:'Un asistente de escritorio para Windows que combina una mascota animada, un chat con IA local y comandos de voz. Desarrollado con React y Tauri, e integrado con Ollama y reconocimiento de voz local.',tags:['React','Tauri','Ollama','Voz'],repo:'Bimu'},soundlify:{title:'Soundlify',image:'soundlify',description:'Un dashboard conectado con Spotify para explorar artistas y canciones destacados en distintos períodos. Presenta un perfil del oyente, características de sus gustos y una distribución de géneros musicales.',tags:['Spotify','Dashboard','Perfil musical']}};
const dialog=document.querySelector('#project-dialog');let previousFocus;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects[button.dataset.project];previousFocus=button;document.querySelector('#dialog-title').textContent=p.title;dialog.setAttribute('aria-labelledby','dialog-title');const image=document.querySelector('#dialog-image');image.src=`assets/${p.image}-real.webp`;image.alt=`Captura real de ${p.title}`;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-tags').replaceChildren(...p.tags.map(t=>{const el=document.createElement('span');el.textContent=t;return el}));const link=document.querySelector('#repo-link');link.hidden=!p.repo;if(p.repo)link.href=`https://github.com/marianoarias1/${p.repo}`;dialog.showModal();document.body.style.overflow='hidden'}));
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus()});
